mapper.select:
SELECT g.* FROM chat_group g


        AND g.id = #{groupId}



        AND g.group_name LIKE CONCAT('%', #{groupName}, '%')


        AND g.owner_name LIKE CONCAT('%', #{ownerName}, '%')



        AND g.create_time >= #{startTime}


        AND g.create_time <= #{endTime}



        AND EXISTS (
        SELECT 1 FROM group_member m
        WHERE m.group_id = g.id
        AND m.user_name LIKE CONCAT('%', #{memberName}, '%')
        )


ORDER BY g.create_time DESC
